<?php
require_once __DIR__ . '/../session_auth.php';
require_once __DIR__ . '/../db.php';
if(!verifyWorkspaceClearance('warehouse.php')){header('Location: ../login.php?msg=err_unauthorized_access');exit;}
if(empty($_SESSION['warehouse_csrf']))$_SESSION['warehouse_csrf']=bin2hex(random_bytes(32));
$sql="SELECT p.id,p.product_name,p.sku,p.price,p.cost_price,p.stock_quantity,p.image,COALESCE(b.brand_name,'Unbranded') brand_name,COALESCE(c.category_name,'Uncategorised') category_name FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id WHERE COALESCE(p.is_deleted,0)=0 ORDER BY p.id DESC";
$products=$conn->query($sql);$rows=[];$units=0;$low=0;$value=0;$uncosted=0;
if($products)while($row=$products->fetch_assoc()){$rows[]=$row;$qty=(int)$row['stock_quantity'];$units+=$qty;if($row['cost_price']!==null&&(float)$row['cost_price']>0){$value+=(float)$row['cost_price']*$qty;}else{$uncosted++;}if($qty<5)$low++;}
?>
<style>
