.inventory-count{align-self:center;color:#687a95;font-size:13px;font-weight:700}.inventory-table-wrap{overflow-x:auto}.inventory-table{width:100%;border-collapse:collapse}.inventory-table th{padding:13px 14px;background:#f7f9fc;color:#5d6c82;font-size:11px;text-align:left;text-transform:uppercase}.inventory-table td{padding:13px 14px;border-top:1px solid #edf1f5;vertical-align:middle}.inventory-product{display:flex;align-items:center;gap:12px;min-width:220px}.inventory-image{width:48px;height:48px;display:grid;place-items:center;overflow:hidden;border:1px solid #e1e8f0;border-radius:9px;background:#eef3f8;color:#718096;font-size:10px}.inventory-image img{width:100%;height:100%;object-fit:cover}.inventory-product strong,.inventory-product small{display:block}.inventory-product small{margin-top:3px;color:#7a899f}.inventory-sku{font-weight:750;color:#52627a}.stock-value{font-weight:800}.stock-badge{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:850}.stock-badge.healthy{background:#e8faf2;color:#078454}.stock-badge.low{background:#fff0ed;color:#d33b32}.stock-badge.out{background:#f1f3f5;color:#596273}.inventory-actions{display:flex;gap:8px}.inventory-action{display:inline-flex;padding:8px 10px;border:1px solid #d1dbe8;border-radius:8px;background:#fff;text-decoration:none;font-size:12px;font-weight:800;cursor:pointer}.inventory-action.edit{color:#345ee8}.inventory-action.delete{color:#d92d20;border-color:#f3c6c2}.inventory-empty{padding:42px!important;text-align:center;color:#75849a}.inventory-row.hidden{display:none}
@media(max-width:900px){.inventory-stats{grid-template-columns:repeat(2,1fr)}.inventory-tools{grid-template-columns:1fr 1fr}.inventory-count{grid-column:1/-1}}@media(max-width:650px){.inventory-hero{align-items:flex-start;flex-direction:column}.inventory-add{width:100%;text-align:center}.inventory-stats,.inventory-tools{grid-template-columns:1fr}.inventory-count{grid-column:auto}.inventory-table thead{display:none}.inventory-table,.inventory-table tbody,.inventory-table tr,.inventory-table td{display:block;width:100%}.inventory-table tr{padding:14px;border-top:1px solid #e7edf4}.inventory-table td{display:flex;justify-content:space-between;gap:14px;padding:7px 4px;border:0}.inventory-table td:before{content:attr(data-label);color:#74839a;font-size:11px;font-weight:800;text-transform:uppercase}.inventory-table td:first-child{display:block}.inventory-table td:first-child:before{display:none}.inventory-actions{justify-content:flex-end}}
.inventory-stats{grid-template-columns:repeat(5,minmax(0,1fr))}.inventory-stat.missing{background:#fff3e8;border-color:#ea6a1b}.inventory-stat.missing span,.inventory-stat.missing strong,.cost-missing{color:#b94708}.cost-missing{font-size:12px;font-weight:800}@media(max-width:900px){.inventory-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.inventory-stats{grid-template-columns:1fr}}
</style>
<section class="inventory-hub">
<header class="inventory-hero"><div><h2>Warehouse Inventory</h2><p>Monitor stock, recorded buying cost and product availability from one workspace.</p></div><div style="display:flex;gap:10px;flex-wrap:wrap"><a href="trash.php" data-target="trash.php" class="inventory-add ajax-link" style="background:#64748b">Trash</a><a href="add_product.php" data-target="add_product.php" class="inventory-add ajax-link">+ Add product</a></div></header>
<div class="inventory-stats"><article class="inventory-stat catalog"><span>Catalog products</span><strong><?=count($rows)?></strong></article><article class="inventory-stat units"><span>Available units</span><strong><?=number_format($units)?></strong></article><article class="inventory-stat low"><span>Low-stock items</span><strong><?=$low?></strong></article><article class="inventory-stat value"><span>Known inventory cost</span><strong>KES <?=number_format($value,2)?></strong></article><article class="inventory-stat missing"><span>Missing buying cost</span><strong><?=$uncosted?></strong></article></div>
<div class="inventory-panel"><div class="inventory-tools"><input id="inventory-search" type="search" placeholder="Search product, SKU, brand or category..." aria-label="Search inventory"><select id="inventory-filter" aria-label="Filter stock status"><option value="all">All stock levels</option><option value="healthy">Healthy stock</option><option value="low">Low stock</option><option value="out">Out of stock</option></select><span class="inventory-count" id="inventory-count"><?=count($rows)?> products</span></div>
<div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Selling price</th><th>Buying cost</th><th>Available</th><th>Status</th><th>Actions</th></tr></thead><tbody id="inventory-body">
<?php if($rows):foreach($rows as $row):$qty=(int)$row['stock_quantity'];$state=$qty===0?'out':($qty<5?'low':'healthy');$label=$state==='out'?'Out of stock':($state==='low'?'Low stock':'Healthy');$img=basename((string)$row['image']);$hasImage=$img!==''&&is_file(__DIR__.'/../uploads/'.$img);$search=strtolower($row['product_name'].' '.$row['sku'].' '.$row['brand_name'].' '.$row['category_name']);?>
<tr class="inventory-row" id="row-item-<?=(int)$row['id']?>" data-search="<?=htmlspecialchars($search)?>" data-status="<?=$state?>">
<td data-label="Product"><div class="inventory-product"><div class="inventory-image"><?php if($hasImage):?><img src="../uploads/<?=rawurlencode($img)?>" alt="<?=htmlspecialchars($row['product_name'])?>"><?php else:?>No image<?php endif;?></div><div><strong><?=htmlspecialchars($row['product_name'])?></strong><small><?=htmlspecialchars($row['brand_name'])?></small></div></div></td>
<td data-label="SKU"><span class="inventory-sku"><?=htmlspecialchars($row['sku'])?></span></td><td data-label="Category"><?=htmlspecialchars($row['category_name'])?></td><td data-label="Selling price"><span class="stock-value">KES <?=number_format((float)$row['price'],2)?></span></td><td data-label="Buying cost"><?php if($row['cost_price']!==null&&(float)$row['cost_price']>0):?><span class="stock-value">KES <?=number_format((float)$row['cost_price'],2)?></span><?php else:?><span class="cost-missing">Not recorded</span><?php endif;?></td><td data-label="Available"><?=number_format($qty)?> units</td><td data-label="Status"><span class="stock-badge <?=$state?>"><?=$label?></span></td>
<td data-label="Actions"><div class="inventory-actions"><a href="edit_product.php?id=<?=(int)$row['id']?>" data-target="edit_product.php?id=<?=(int)$row['id']?>" class="inventory-action edit ajax-link">Edit</a><button type="button" class="inventory-action delete async-delete-btn" data-id="<?=(int)$row['id']?>" data-name="<?=htmlspecialchars($row['product_name'])?>" data-csrf="<?=htmlspecialchars($_SESSION['warehouse_csrf'])?>">Move to Trash</button></div></td></tr>
<?php endforeach;else:?><tr><td class="inventory-empty" colspan="8">No products are currently registered.</td></tr><?php endif;?>
<tr id="inventory-no-results" class="hidden"><td class="inventory-empty" colspan="8">No products match the selected filters.</td></tr></tbody></table></div></div></section>
<script>
(function(){const search=document.getElementById('inventory-search'),filter=document.getElementById('inventory-filter'),count=document.getElementById('inventory-count'),none=document.getElementById('inventory-no-results');function apply(){const q=(search.value||'').trim().toLowerCase(),state=filter.value;let shown=0;document.querySelectorAll('.inventory-row').forEach(row=>{const visible=(!q||row.dataset.search.includes(q))&&(state==='all'||row.dataset.status===state);row.classList.toggle('hidden',!visible);if(visible)shown++;});count.textContent=shown+(shown===1?' product':' products');none.classList.toggle('hidden',shown!==0);}search.addEventListener('input',apply);filter.addEventListener('change',apply);})();
</script>